"""it — virtues_c."""

T = {
"virtues_051": ("Che cosa consiglia Luqman a suo figlio riguardo alla voce?", ["Abbassarla: la più sgradevole delle voci è il raglio dell'asino", "Parlare fortissimo", "Non parlare mai", "Cantare camminando"], "«Sii modesto nel tuo passo e abbassa la voce: in verità la più sgradevole delle voci è quella degli asini.»"),
"virtues_052": ("Quali tre consigli dà Luqman a suo figlio prima di parlare di pazienza?", ["Assolvere alla preghiera, ordinare il bene, proibire il male", "Viaggiare, commerciare, scrivere", "Mangiare poco, dormire poco, parlare poco", "Costruire, piantare, raccogliere"], "«O figlio mio, assolvi all'orazione, ordina il bene, proibisci il male e sopporta con pazienza ciò che ti accade.»"),
"virtues_053": ("Quali tre qualità attribuisce il Corano ai timorati, nella sura Al-'Imran?", ["Donare nell'agiatezza e nelle difficoltà, dominare la collera, perdonare gli uomini", "Digiuno, preghiera notturna, silenzio", "Costruire, piantare, donare", "Viaggiare, imparare, insegnare"], "«Quelli che donano nell'agiatezza e nelle ristrettezze, che dominano la collera e perdonano agli uomini: Allah ama coloro che fanno il bene.»"),
"virtues_054": ("Che cosa considera il Corano migliore di un'elemosina seguita da un'offesa?", ["Una parola gentile e il perdono", "Un dono più grande", "Il silenzio totale", "Un giuramento"], "«Una parola gentile e il perdono sono migliori di un'elemosina seguita da un'offesa.»"),
"virtues_055": ("Che cosa dice il Corano dell'elemosina data in segreto?", ["È migliore per chi la dà", "Non conta", "Va annunciata", "È vietata"], "«Se palesate le vostre elemosine, è un bene; ma se le nascondete e le date ai poveri, è meglio per voi.»"),
"virtues_056": ("Che cosa vieta il Corano di dare in elemosina?", ["Ciò che si accetterebbe solo a occhi chiusi", "Ciò che è nuovo", "Ciò che si ama", "Ciò che viene da un'eredità"], "«E non scegliete appositamente il peggio per darlo in elemosina, ciò che voi stessi accettereste solo chiudendo gli occhi.»"),
"virtues_057": ("Quando si raggiunge la vera pietà, secondo la sura Al-'Imran?", ["Donando ciò che si ama", "Donando il superfluo", "Donando in pubblico", "Conservando tutto"], "«Non raggiungerete la pietà finché non avrete dato di ciò che amate.»"),
"virtues_058": ("Quale immagine usa il Corano per l'equilibrio nella spesa?", ["Non tenere la mano incatenata al collo, né allungarla del tutto", "Chiudere la porta", "Camminare lentamente", "Contare due volte"], "«Non portare la mano incatenata al collo, né aprirla senza alcun ritegno, ché ti ritroveresti biasimato e spoglio.»"),
"virtues_059": ("Come descrive il Corano la spesa dei «servi del Compassionevole»?", ["Né prodighi né avari, ma in una giusta misura", "Donano sempre senza misura", "Risparmiano sempre", "Non donano mai"], "«E coloro che, quando spendono, non sono né prodighi né avari, ma stanno nel giusto mezzo.»"),
"virtues_060": ("Che cosa ordina il Corano prima di entrare in una casa che non è la propria?", ["Chiedere permesso e salutare i suoi abitanti", "Bussare tre volte poi entrare", "Entrare direttamente", "Chiamare da lontano"], "«Non entrate in case che non siano le vostre senza aver chiesto il permesso e senza aver salutato i loro abitanti.»"),
"virtues_061": ("Che cosa si deve fare se viene chiesto di tornare indietro, secondo la sura An-Nur?", ["Tornare indietro: è più puro per voi", "Insistere", "Attendere alla porta", "Entrare comunque"], "«E se vi si dice: “Tornate indietro”, allora tornate indietro: è più puro per voi.»"),
"virtues_062": ("Che cosa ordina il Corano quando una persona poco affidabile porta una notizia?", ["Verificarla, per non danneggiare qualcuno per ignoranza", "Diffonderla subito", "Metterla per iscritto", "Ignorarla sempre"], "«Se un malvagio vi reca una notizia, verificatela, affinché non danneggiate qualcuno per ignoranza e poi dobbiate pentirvene.»"),
"virtues_063": ("Quale comportamento, accanto alla maldicenza, vieta la sura Al-Hujurat?", ["Lo spiare e il sospetto eccessivo", "Viaggiare da soli", "Parlare a bassa voce", "Scrivere lettere"], "«O voi che credete, evitate di far troppe illazioni: alcune illazioni sono peccato. Non spiatevi e non sparlate gli uni degli altri.»"),
"virtues_064": ("Che cosa ordina il Corano quando due gruppi di credenti si combattono?", ["Riconciliarli con giustizia", "Prendere le parti di uno", "Ignorarli", "Separarli con la sola forza"], "«Se due gruppi di credenti combattono tra loro, riconciliateli… e siate equi: in verità Allah ama coloro che sono equi.»"),
"virtues_065": ("Che cosa vieta espressamente il Corano, anche verso un popolo che si detesta?", ["Lasciare che l'odio allontani dalla giustizia", "Il commercio", "La parola", "Il vicinato"], "«Non lasciate che l'odio verso un popolo vi spinga a essere ingiusti. Siate equi: questo è più vicino al timore di Allah.»"),
"virtues_066": ("Contro chi il Corano esige una testimonianza giusta, se necessario?", ["Contro se stessi, i propri genitori e i propri parenti", "Solo contro gli estranei", "Solo contro i ricchi", "Solo contro i poveri"], "«Siate testimoni sinceri davanti ad Allah, sostenendo la giustizia, anche contro voi stessi, i vostri genitori o i vostri parenti.»"),
"virtues_067": ("Che cosa ordina il Corano di restituire a chi ne ha diritto?", ["I depositi affidati (amanat)", "Le lettere", "I raccolti", "I racconti"], "«In verità Allah vi ordina di restituire i depositi ai loro aventi diritto e, quando giudicate tra gli uomini, di giudicare con giustizia.»"),
"virtues_068": ("Quali persone elenca il versetto 4:36 per il buon trattamento, dopo i genitori?", ["I parenti, gli orfani, i poveri, il vicino prossimo e lontano, il compagno, il viandante e il servo", "I re e i capi", "I mercanti", "Solo i dotti"], "«Adorate Allah e non associateGli nulla; e siate buoni con i genitori, i parenti, gli orfani, i bisognosi, il vicino prossimo e il vicino lontano, il compagno al vostro fianco, il viandante e coloro che sono nelle vostre mani.»"),
"virtues_069": ("Che cosa ordina il Corano verso un debitore in difficoltà?", ["Concedergli tempo fino all'agiatezza", "Perseguitarlo", "Raddoppiare il debito", "Cacciarlo"], "«Chi è in difficoltà, gli sia concesso tempo fino a che si trovi nell'agiatezza; ma se rimettete il debito in elemosina, è meglio per voi.»"),
"virtues_070": ("Che cosa ordina il versetto più lungo del Corano per un debito con termine fissato?", ["Che sia messo per iscritto", "Che sia tenuto segreto", "Che sia dimenticato", "Che sia trasmesso a voce"], "«O voi che credete, quando contraete un debito con scadenza determinata, mettetelo per iscritto.»"),
"virtues_071": ("Che cosa vieta il Corano riguardo ai beni altrui?", ["Consumarli ingiustamente, o servirsene per corrompere i giudici", "Contarli", "Venderli", "Conservarli"], "«Non divorate ingiustamente i beni gli uni degli altri, e non datene ai giudici per divorare peccaminosamente una parte dei beni della gente.»"),
"virtues_072": ("Che cosa ordina il Corano riguardo ai beni degli orfani?", ["Consegnarli loro, senza scambiare il buono con il cattivo", "Dividerli", "Venderli", "Conservarli per sempre"], "«Restituite agli orfani i loro beni e non scambiate il cattivo con il buono, e non consumate i loro beni insieme ai vostri.»"),
"virtues_073": ("Come ordina il Corano di misurare e pesare?", ["Dare la misura piena e pesare con bilancia esatta", "Arrotondare a proprio favore", "Pesare a occhio", "Misurare due volte"], "«Riempite la misura quando misurate e pesate con bilancia esatta: questo è il bene e il miglior esito.»"),
"virtues_074": ("Che cosa vieta il Corano di seguire, in mancanza di conoscenza?", ["Ciò di cui non si ha conoscenza: udito, vista e cuore saranno interrogati", "La strada più breve", "Le carovane", "Il silenzio"], "«Non seguire ciò di cui non hai conoscenza: in verità l'udito, la vista e il cuore, di tutto questo sarà chiesto conto.»"),
"virtues_075": ("Quale immagine dà il Corano dell'orgoglio nel camminare?", ["Non puoi spaccare la terra, né raggiungere in altezza le montagne", "Si va più veloci", "Si fa meno fatica", "Si guadagna rispetto"], "«Non camminare sulla terra con arroganza: non potrai spaccare la terra, né raggiungere l'altezza delle montagne.»"),
"virtues_076": ("Quale qualità della parola ordina il Corano, promettendo che le opere saranno rese buone?", ["Una parola retta e veritiera (qawl sadid)", "Una parola breve", "Una parola dotta", "Una parola scritta"], "«O voi che credete, temete Allah e dite parole rette: Egli renderà buone le vostre opere e vi perdonerà i vostri peccati.»"),
"virtues_077": ("Quale genere di parola fu ordinato persino davanti a un tiranno, nel Corano?", ["Una parola dolce", "Una parola minacciosa", "Una parola ironica", "Il silenzio"], "«E parlategli con dolcezza: forse ricorderà o temerà Allah.»"),
"virtues_078": ("Di chi dice il Corano che la sua parola è la migliore?", ["Di chi chiama ad Allah, compie il bene e dice: sono tra i musulmani", "Del poeta", "Dell'oratore", "Del giudice"], "«E chi mai è migliore, nel parlare, di colui che invita ad Allah, compie il bene e dice: “In verità sono tra i musulmani”?»"),
"virtues_079": ("Da che cosa si distolgono i credenti che avranno successo, secondo Al-Mu'minun?", ["Dalle chiacchiere vane (al-laghw)", "Dal lavoro", "Dai viaggi", "Dai pasti"], "«E che evitano le chiacchiere vane.»"),
"virtues_080": ("Quali due impegni custodiscono i credenti che avranno successo, secondo Al-Mu'minun?", ["I depositi loro affidati e i loro patti", "Il digiuno e la preghiera notturna", "Il viaggio e il commercio", "La scrittura e la lettura"], "«E che si preoccupano dei depositi loro affidati e dei loro impegni.»"),
"virtues_081": ("Che cosa dice il Corano di chi perdona e riconcilia, pur potendo rendere il male?", ["La sua ricompensa spetta ad Allah", "Perde il suo diritto", "È biasimato", "Deve tacere"], "«La sanzione di un male è un male equivalente, ma chi perdona e si riconcilia, la sua ricompensa spetta ad Allah.»"),
"virtues_082": ("Quale argomento dà il Corano per perdonare chi ti ha fatto torto?", ["«Non desiderate forse che Allah vi perdoni?»", "«Sarai pagato in denaro»", "«Ti renderà potente»", "«Ti eviterà un processo»"], "«Perdonino e passino oltre. Non desiderate che Allah vi perdoni? Allah è perdonatore, misericordioso.»"),
"virtues_083": ("Quali tre indicazioni riunisce il versetto 7:199?", ["Prendere ciò che è dato spontaneamente, ordinare il bene, allontanarsi dagli ignoranti", "Combattere, fuggire, tacere", "Mangiare, bere, dormire", "Contare, scrivere, leggere"], "«Prendi ciò che ti è dato spontaneamente, ordina il bene e allontanati dagli ignoranti.»"),
"virtues_084": ("Quale atteggiamento raccomanda il Corano di fronte alle parole offensive e alla prova?", ["La pazienza e il timore di Allah: è questo che richiede fermezza", "La replica immediata", "Il ritiro definitivo", "Il silenzio sprezzante"], "«Sentirete molte offese da coloro che ricevettero la Scrittura prima di voi. Ma se sarete pazienti e timorati, ecco ciò che richiede fermezza.»"),
"virtues_085": ("Come descrive il Corano la pazienza e il perdono?", ["Sono tra le cose che richiedono fermezza", "Sono debolezza", "Sono facoltativi", "Sono per i soli dotti"], "«E chi è paziente e perdona, ecco ciò che richiede davvero fermezza.»"),
"virtues_086": ("Per chi il Corano dice che la preghiera non è un peso?", ["Per gli umili (al-khashi'in)", "Per i ricchi", "Per i dotti", "Per i viaggiatori"], "«Cercate aiuto nella pazienza e nell'orazione: in verità è gravosa, tranne che per gli umili.»"),
"virtues_087": ("Che cosa ricorda il Corano riguardo a ciò che si detesta o si ama?", ["Puoi detestare una cosa che è un bene per te, e amare una cosa che è un male", "Ciò che ami è sempre un bene", "Ciò che detesti è sempre un male", "Sai sempre ciò che è bene"], "«Può darsi che detestiate una cosa che è un bene per voi, e che amiate una cosa che è un male per voi. Allah sa e voi non sapete.»"),
"virtues_088": ("Che cosa promette il Corano a chi teme Allah, quanto alla via d'uscita e al sostentamento?", ["Una via d'uscita, e un sostentamento da dove non se lo aspetta", "Una ricchezza immediata", "Un lungo viaggio", "Una carica pubblica"], "«A chi teme Allah, Egli apre una via d'uscita e provvede da dove non se lo aspetta.»"),
"virtues_089": ("Quale gratitudine ordina il Corano nello stesso respiro della gratitudine verso Allah?", ["La gratitudine verso i genitori", "Verso il proprio padrone", "Verso il proprio vicino", "Verso il proprio re"], "«Sii riconoscente a Me e ai tuoi genitori: verso di Me è il ritorno finale.»"),
"virtues_090": ("Quale limite pone il Corano all'obbedienza ai genitori?", ["Non obbedire loro se ordinano di associare altri ad Allah", "Non obbedire loro mai", "Obbedire loro in tutto", "Obbedire loro solo in viaggio"], "«Ma se si sforzano di farti associare a Me ciò di cui non hai conoscenza, non obbedire loro; e accompagnali in questo mondo con dolcezza.»"),
"virtues_091": ("Quale invocazione insegna il Corano per i propri genitori e la propria discendenza?", ["Essere grati per il favore, compiere il bene, e che la propria discendenza sia resa buona", "Chiedere la ricchezza", "Chiedere un lungo viaggio", "Chiedere una carica"], "«Signore, permettimi di essere grato per il favore che hai concesso a me e ai miei genitori, e di compiere il bene; e rendi buona la mia discendenza.»"),
"virtues_092": ("Che cosa chiedono «i servi del Compassionevole» riguardo alle loro famiglie?", ["Che siano conforto degli occhi, e che essi siano un esempio per i timorati", "Che siano ricchi", "Che siano numerosi", "Che viaggino"], "«Signore, dacci conforto negli occhi nelle nostre spose e nella nostra discendenza, e fai di noi un esempio per i timorati.»"),
"virtues_093": ("Come si comportano «i servi del Compassionevole» di fronte alla frivolezza?", ["Passano oltre con dignità", "Si fermano ad ascoltare", "Rispondono aspramente", "La mettono per iscritto"], "«E coloro che non testimoniano il falso e, quando passano vicino a discorsi vani, passano oltre con dignità.»"),
"virtues_094": ("Che cosa ordina il Corano in un'assemblea quando si chiede posto?", ["Fare posto: Allah farà posto a voi", "Restare stretti", "Andarsene", "Tacere"], "«O voi che credete, quando vi si dice: “Fate largo nelle assemblee”, fate largo: Allah farà largo per voi.»"),
"virtues_095": ("Con chi ordina il Corano di stare, nella sura At-Tawbah?", ["Con i sinceri", "Con i potenti", "Con i ricchi", "Con i viaggiatori"], "«O voi che credete, temete Allah e state con i sinceri.»"),
"virtues_096": ("Con chi ordina il Corano al Profeta ﷺ di restare pazientemente, in Al-Kahf?", ["Con coloro che invocano il loro Signore al mattino e alla sera, cercando il Suo volto", "Con i capi tribù", "Con i ricchi mercanti", "Con i poeti"], "«Sii paziente insieme a coloro che invocano il loro Signore al mattino e alla sera, cercando il Suo volto; e non distogliere da loro i tuoi occhi.»"),
"virtues_097": ("Su che cosa ordina il Corano l'aiuto reciproco, e su che cosa lo vieta?", ["Aiutarsi nella bontà e nella pietà, non nel peccato e nell'aggressione", "Aiutarsi in tutto", "Non aiutare nessuno", "Aiutarsi solo in famiglia"], "«Aiutatevi l'un l'altro nella bontà e nella pietà, e non aiutatevi nel peccato e nella trasgressione.»"),
"virtues_098": ("Che cosa ordina il Corano riguardo a un patto stretto e ai giuramenti confermati?", ["Mantenere il patto e non rompere i giuramenti dopo averli confermati", "Rinegoziarli", "Dimenticarli", "Nasconderli"], "«Rispettate il patto di Allah, dopo che l'avete stretto, e non rompete i giuramenti dopo averli confermati.»"),
"virtues_099": ("Secondo un hadith riportato da al-Bukhari, quando è completa la fede di un uomo?", ["Quando ama per suo fratello ciò che ama per se stesso", "Quando digiuna tutto l'anno", "Quando dona tutti i suoi beni", "Quando viaggia alla Mecca"], "«Nessuno di voi crede veramente finché non ama per suo fratello ciò che ama per se stesso.»"),
"virtues_100": ("In quali casi il Corano vede del bene in un colloquio privato?", ["Quando si esorta all'elemosina, a un'opera buona o alla riconciliazione tra le persone", "Quando si parla d'affari", "Quando si prepara un viaggio", "Quando si riferiscono notizie"], "«Non c'è alcun bene nella maggior parte dei loro colloqui privati, eccetto in chi esorta all'elemosina, al bene o alla riconciliazione tra le persone.»"),
}
